export const VISUALS: readonly GalleryVisual[] = [
  {"slug":"neet-limiting-reagent","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"some-basic-concepts","chapterName":"Some Basic Concepts of Chemistry","subtopicSlug":"nch-sb-stoichiometry","subtopicTitle":"Stoichiometry","conceptSlug":"nchsb-limiting","conceptName":"Limiting reagent","line":"When reactants are not mixed in the exact ratio of the equation, one runs out first and the reaction stops. That reactant, the limiting reagent, decides how much product forms. Whatever is left of the other reactant is the excess.","pyqExampleId":"4b9197c9-a6f9-4fd6-b364-479ebbda96c4","badge":"picture","interactive":false},
  {"slug":"imat-aufbau-filling","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"structure-of-atom","chapterName":"Structure of Atom","subtopicSlug":"nch-sa-orbitals","subtopicTitle":"Quantum Numbers and Orbitals","conceptSlug":"nchsa-filling","conceptName":"Filling orbitals: the (n + l) rule, Pauli and Hund","line":"Electrons go into the lowest energy orbital first, like filling a building from the ground floor. In atoms with many electrons the order is not simply by n: a 4s orbital is lower than 3d. The (n + l) rule gives the order, Pauli's principle limits each orbital to two electrons, and Hund's rule says how they spread over orbitals of equal energy.","pyqExampleId":"ac42313b-517f-4377-8fe0-999b6de1aabc","badge":"try","interactive":true},
  {"slug":"atom-periodic-trends","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"classification-of-elements","chapterName":"Classification of Elements and Periodicity in Properties","subtopicSlug":"nch-cp-size","subtopicTitle":"Atomic Size and Ionisation Enthalpy","conceptSlug":"nchcp-atomic-radius","conceptName":"Atomic radius across a period and down a group","line":"Across a period, each new electron goes into the same outer shell while the nuclear charge rises by one. The bigger effective nuclear charge pulls the whole electron cloud in, so the atom shrinks. Down a group, every step adds a new shell further from the nucleus, and the inner electrons shield the outer ones, so the atom grows.","pyqExampleId":"e97abedf-0ac2-48cb-98f7-b2996eb1c3a8","badge":"picture","interactive":false},
  {"slug":"imat-vsepr-shapes","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"chemical-bonding","chapterName":"Chemical Bonding and Molecular Structure","subtopicSlug":"nch-cb-shapes","subtopicTitle":"VSEPR, Hybridisation and Shapes","conceptSlug":"nchcb-vsepr","conceptName":"VSEPR theory and the shapes of molecules","line":"Electron pairs around a central atom repel each other, so they spread out as far apart as they can. Count the pairs, bond pairs and lone pairs together, and that number fixes how they are arranged. The shape you name is then where the ATOMS are, so lone pairs count for the arrangement but are invisible in the shape's name. Lone pairs also repel more strongly than bond pairs, which squeezes the bond angles.","pyqExampleId":"dce153c3-65b4-4deb-8db9-cd7f34be8c68","badge":"picture","interactive":false},
  {"slug":"jee-mo-diagram","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"chemical-bonding","chapterName":"Chemical Bonding and Molecular Structure","subtopicSlug":"nch-cb-mot","subtopicTitle":"Molecular Orbital Theory","conceptSlug":"nchcb-mo-order","conceptName":"Molecular orbitals and their energy order","line":"When two atoms come together, their atomic orbitals combine into molecular orbitals that belong to the whole molecule. Each pair of atomic orbitals gives two: a bonding orbital lower in energy, which holds the atoms together, and an antibonding orbital (marked with a star) higher in energy, which pushes them apart. Electrons fill these from the lowest energy up, like electrons in an atom.","pyqExampleId":"fc9f1ef0-0671-470c-b29c-6331f9dcc375","badge":"picture","interactive":false},
  {"slug":"neet-chem-pv-work","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"nch-th-first-law","subtopicTitle":"The First Law and Work","conceptSlug":"ncht-work","conceptName":"Work of expansion","line":"A gas that expands pushes back whatever holds it in, the piston and the air beyond it, and so does work. The work depends on the pressure it pushes against and on how far the volume changes. If the gas expands slowly, with the outside pressure kept only a little below its own at every stage, it pushes against the largest pressure it can and does the most work.","pyqExampleId":"428fd03b-4b79-4219-9cd5-06694dd9a0a5","badge":"picture","interactive":false},
  {"slug":"imat-energy-profile","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"nch-th-enthalpy","subtopicTitle":"Enthalpy and Thermochemistry","conceptSlug":"ncht-reaction-enthalpy","conceptName":"Reaction enthalpy and standard enthalpy of formation","line":"A reaction either gives heat out or takes it in. If the products hold less enthalpy than the reactants, the difference is released: the reaction is exothermic and ΔH is negative. If the products hold more, the reaction must absorb heat: it is endothermic and ΔH is positive. To compare reactions fairly we fix the conditions, and we measure every compound from the same zero: its elements.","pyqExampleId":"8e866383-69e8-4959-ade8-05d87e0ffc6a","badge":"picture","interactive":false},
  {"slug":"cet-hess-cycle","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"nch-th-enthalpy","subtopicTitle":"Enthalpy and Thermochemistry","conceptSlug":"ncht-hess","conceptName":"Hess's law and enthalpies of different types","line":"Enthalpy is a state function, so the enthalpy change from reactants to products is the same whether the reaction goes in one step or in several. That lets you treat thermochemical equations like algebra: add them, reverse them, multiply them, and their ΔH values follow along. Many enthalpies that cannot be measured directly, such as the formation of CO or the lattice enthalpy of a salt, are found this way.","pyqExampleId":"a7d0cba2-a8d4-4d5d-b94f-7c907dcd0780","badge":"try","interactive":true},
  {"slug":"cet-gibbs-sign","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"nch-th-spontaneity","subtopicTitle":"Entropy and Gibbs Energy","conceptSlug":"ncht-gibbs","conceptName":"Gibbs energy and spontaneity","line":"Working out the entropy of the surroundings every time is awkward. Gibbs energy rolls both tests into one quantity about the system alone. At constant temperature and pressure, a change is spontaneous when it lowers the Gibbs energy. A negative ΔH helps, a positive ΔS helps, and the temperature decides how much weight the entropy term gets.","pyqExampleId":"14bd8331-71c4-4668-80f3-a6aaa2118fd5","badge":"try","interactive":true},
  {"slug":"imat-le-chatelier","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"equilibrium","chapterName":"Equilibrium","subtopicSlug":"nch-eq-shifts","subtopicTitle":"Reaction Quotient and Le Chatelier's Principle","conceptSlug":"ncheq-le-chatelier","conceptName":"Le Chatelier's principle: concentration and pressure","line":"Le Chatelier's principle says that when an equilibrium is disturbed, it shifts in the direction that undoes the disturbance. Add a reactant, and the reaction uses some of it up by going forward. Squeeze a gas mixture, and the reaction moves to the side with fewer gas molecules, which lowers the pressure.","pyqExampleId":"88d13090-2f6d-4c75-997c-67fa2e2310a0","badge":"try","interactive":true},
  {"slug":"acid-ph-scale-strip","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"equilibrium","chapterName":"Equilibrium","subtopicSlug":"nch-eq-acids","subtopicTitle":"Acids, Bases and pH","conceptSlug":"ncheq-ph","conceptName":"Kw, pH and weak acids","line":"Even pure water ionises a little, into H⁺ and OH⁻, and the product of their concentrations is a constant at a given temperature. pH is just a short way of writing a tiny H⁺ concentration: take the log and change the sign. A weak acid ionises only partly, and how far it goes is set by its ionisation constant Ka.","pyqExampleId":"1e71761a-9937-4005-b545-f9251e9f688d","badge":"picture","interactive":false},
  {"slug":"imat-titration-curve","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"equilibrium","chapterName":"Equilibrium","subtopicSlug":"nch-eq-acids","subtopicTitle":"Acids, Bases and pH","conceptSlug":"ncheq-indicators","conceptName":"Indicators in acid-base titrations","line":"An indicator is a weak acid or weak base whose two forms have different colours, so it changes colour over a small range of pH. At the end point of a titration of a weak acid with a strong base, the salt formed makes the solution slightly alkaline. So the indicator chosen must change colour in the alkaline range. Phenolphthalein does: colourless in acid, pink in alkali.","pyqExampleId":"c0c1d5e2-aed2-4b2c-a822-a4b724f33809","badge":"picture","interactive":false},
  {"slug":"neet-redox-balance","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"redox-reactions","chapterName":"Redox Reactions","subtopicSlug":"nch-rr-reactions","subtopicTitle":"Types and Balancing of Redox Reactions","conceptSlug":"nchrr-balancing","conceptName":"Balancing redox equations","line":"In a balanced redox equation the electrons given up by the reducing agent are exactly the electrons taken by the oxidising agent. Both balancing methods rest on this. The half-reaction method writes the oxidation and the reduction separately, balances each, then multiplies them so their electrons match. The oxidation number method counts the rise and the fall in oxidation number and makes them equal.","pyqExampleId":"1387bcb2-e8bb-430f-bee9-ec781fbd2ea5","badge":"picture","interactive":false},
  {"slug":"neet-carbocation-stability","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"organic-basic-principles","chapterName":"Organic Chemistry – Some Basic Principles and Techniques","subtopicSlug":"nch-oc-effects","subtopicTitle":"Electronic Effects","conceptSlug":"nchoc-carbocation","conceptName":"What makes a carbocation stable","line":"The positive carbon has an empty p orbital. Anything that can feed electrons into that orbital spreads the positive charge and steadies the ion. A C-H bond on the next carbon can lean its σ electrons into it: that is hyperconjugation, and more such hydrogens means more help. A double bond or a benzene ring next to the positive carbon can feed in its π electrons: that is resonance. Either way the electrons must come from a filled orbital, because an empty orbital has nothing to give.","pyqExampleId":"1654ee55-326f-4cd9-8b1e-377622dd8278","badge":"picture","interactive":false},
  {"slug":"neet-ethane-conformations","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"hydrocarbons","chapterName":"Hydrocarbons","subtopicSlug":"nch-hc-alkanes","subtopicTitle":"Alkanes","conceptSlug":"nchhc-conformations","conceptName":"Conformations of ethane","line":"The two carbons of ethane can turn about their single bond. Look straight down that bond. If the hydrogens of the back carbon sit exactly behind those of the front one, their bond pairs crowd each other: the eclipsed form. If they sit in the gaps, they are as far apart as they can be: the staggered form. The crowding is called torsional strain, so staggered is the most stable form and eclipsed the least.","pyqExampleId":"ec3426fa-cd65-49db-a703-4bd16bb20e6d","badge":"picture","interactive":false},
  {"slug":"imat-cis-trans","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"hydrocarbons","chapterName":"Hydrocarbons","subtopicSlug":"nch-hc-alkenes","subtopicTitle":"Alkenes and Alkynes","conceptSlug":"nchhc-alkene-isomerism","conceptName":"The double bond, geometrical isomers and conjugation","line":"A C=C double bond is one σ bond and one π bond. The π bond is made by sideways overlap of p orbitals, so the two carbons cannot turn about the bond without breaking it. That locked bond is why groups can sit on the same side (cis) or opposite sides (trans), and the two forms are different compounds. But if one carbon carries two identical groups, swapping sides changes nothing, so there is no cis-trans pair.","pyqExampleId":"41b835b4-ba05-4440-95d6-687d1170604e","badge":"picture","interactive":false},
  {"slug":"cet-directing-effects","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"hydrocarbons","chapterName":"Hydrocarbons","subtopicSlug":"nch-hc-aromatic","subtopicTitle":"Aromatic Hydrocarbons","conceptSlug":"nchhc-eas","conceptName":"Reactions of benzene and directing groups","line":"Benzene's ring of π electrons attracts electrophiles, but adding to the ring would destroy the special stability. So benzene prefers to swap a hydrogen for the electrophile and keep its ring of six π electrons: electrophilic substitution. Only under harsh conditions (UV light, or hydrogen with nickel at high temperature and pressure) does it add. When the ring already carries a group, that group decides where the next one goes.","pyqExampleId":"3c922d4e-5f67-454e-a536-4c5cac70f5c9","badge":"picture","interactive":false},
  {"slug":"jee-raoult-deviations","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"solutions","chapterName":"Solutions","subtopicSlug":"nch-so-raoult","subtopicTitle":"Raoult's Law and Deviations","conceptSlug":"nchso-deviations","conceptName":"Ideal and non-ideal solutions","line":"Raoult's law holds exactly only when a molecule of A is held by B just as strongly as by another A. If mixing makes the attractions weaker, molecules escape more easily and the vapour pressure comes out higher than Raoult's law predicts. If mixing makes them stronger, often through a new hydrogen bond, the vapour pressure comes out lower. To decide, work out the Raoult's law value and compare it with the measured one.","pyqExampleId":"2648df17-ef18-4479-b62a-78f105e30795","badge":"picture","interactive":false},
  {"slug":"cet-boiling-point-elevation","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"solutions","chapterName":"Solutions","subtopicSlug":"nch-so-colligative","subtopicTitle":"Colligative Properties","conceptSlug":"nchso-boiling-freezing","conceptName":"Boiling point, freezing point and the van 't Hoff factor","line":"A non-volatile solute takes up part of the surface, so fewer solvent molecules escape and the vapour pressure falls. The solution then has to be heated further before its vapour pressure reaches the atmospheric pressure, so it boils higher; it also freezes lower than the pure solvent. These changes depend only on how many solute particles there are, not on what they are. A salt that splits into ions gives more particles, and the van 't Hoff factor counts them.","pyqExampleId":"4a58db76-92df-4872-84c5-97fdfce0d951","badge":"picture","interactive":false},
  {"slug":"imat-galvanic-cell","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"electrochemistry","chapterName":"Electrochemistry","subtopicSlug":"nch-ec-cells","subtopicTitle":"Galvanic Cells and Electrode Potentials","conceptSlug":"nchec-ecell","conceptName":"Galvanic cells and E°cell","line":"A galvanic cell keeps the two halves of a redox reaction apart, so the electrons must travel through a wire to get from one to the other, and that flow is a current. In the Daniell cell zinc is oxidised and Cu²⁺ is reduced. The couple with the higher E° wins the electrons and is reduced at the cathode; the other couple runs backwards and is oxidised at the anode. The cell voltage is the gap between the two potentials.","pyqExampleId":"f834e980-b442-4b6b-aca1-c607823fa910","badge":"picture","interactive":false},
  {"slug":"neet-order-plots","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"chemical-kinetics","chapterName":"Chemical Kinetics","subtopicSlug":"nch-ck-integrated","subtopicTitle":"Integrated Rate Laws and Half-Life","conceptSlug":"nchck-plots","conceptName":"Plots that show the order","line":"Each integrated rate law turns into a straight line when you choose the right axes. So a graph tells you the order: find which pair of quantities gives a straight line, or which one stays flat. Always read the axes before the shape.","pyqExampleId":"ae1ef709-0745-4c17-b7db-2e38b4b24f7a","badge":"picture","interactive":false},
  {"slug":"imat-catalyst-profile","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"chemical-kinetics","chapterName":"Chemical Kinetics","subtopicSlug":"nch-ck-temperature","subtopicTitle":"Temperature and Activation Energy","conceptSlug":"nchck-energy-profile","conceptName":"Activation energy, energy profiles and catalysts","line":"Reactant molecules cannot turn straight into products. They must first climb an energy hill to an unstable arrangement called the activated complex, and only then roll down to products. The height of the hill above the reactants is the activation energy. A catalyst does not move the reactants or the products; it opens a lower path over the hill.","pyqExampleId":"d4f339c0-18e2-4f60-849d-88c666fb689b","badge":"try","interactive":true},
  {"slug":"neet-xenon-shapes","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"p-block-elements","chapterName":"The p-Block Elements","subtopicSlug":"nch-pb-halogens","subtopicTitle":"Halogens and Noble Gases","conceptSlug":"nchpb-xenon","conceptName":"Xenon compounds: preparation, hybridisation and shape","line":"Xenon has eight outer electrons. In a xenon compound some pair up with fluorine or oxygen, and the rest stay as lone pairs. Count the σ bond pairs and the lone pairs on xenon; their total gives the hybridisation (5 pairs sp³d, 6 pairs sp³d², 7 pairs sp³d³), and the bond pairs alone give the shape, exactly as in VSEPR.","pyqExampleId":"3c2ca804-8629-4648-b22f-d0babdf7de6d","badge":"picture","interactive":false},
  {"slug":"neet-spin-only-moment","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"d-and-f-block-elements","chapterName":"The d- and f-Block Elements","subtopicSlug":"nch-df-magnetic","subtopicTitle":"Magnetic Moment and Colour","conceptSlug":"nchdf-spin-only","conceptName":"The spin-only magnetic moment","line":"Each unpaired electron adds to the ion's magnetic moment. Once you know the number of unpaired electrons n, one formula gives the moment in Bohr magnetons. It is the same formula used for complexes in Coordination Compounds.","pyqExampleId":"28284ac8-be90-44e5-92da-59a71f4f6eac","badge":"picture","interactive":false},
  {"slug":"neet-lanthanoid-contraction","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"d-and-f-block-elements","chapterName":"The d- and f-Block Elements","subtopicSlug":"nch-df-lanthanoids","subtopicTitle":"Lanthanoids and Actinoids","conceptSlug":"nchdf-contraction","conceptName":"Lanthanoid contraction","line":"Going from lanthanum to lutetium, each step adds one proton to the nucleus and one electron to the 4f subshell. A 4f electron is poor at shielding another 4f electron from the nucleus, so the outer electrons feel a slightly stronger pull each time and the atom shrinks a little. Fourteen small shrinkages add up to a large one, big enough to cancel the usual growth in size on going down a group.","pyqExampleId":"696c53df-9890-4df5-9321-555d56a4abee","badge":"picture","interactive":false},
  {"slug":"cet-d-electron-pairing","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"coordination-compounds","chapterName":"Coordination Compounds","subtopicSlug":"nch-cc-vbt","subtopicTitle":"Valence Bond Theory and Magnetic Moments","conceptSlug":"nchcc-vbt","conceptName":"Hybridisation and shape by valence bond theory","line":"In valence bond theory the metal ion mixes some of its empty s, p and d orbitals into a set of equal hybrid orbitals, one for each ligand. Each ligand puts a lone pair into one of them. The kind of hybrid sets the shape. A strong-field ligand can push the metal's d electrons to pair up, which empties inner d orbitals for the hybrid set and leaves fewer unpaired electrons.","pyqExampleId":"855db9fb-507f-41a4-b05e-a1fd09c45cc6","badge":"try","interactive":true},
  {"slug":"jee-crystal-field-splitting","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"coordination-compounds","chapterName":"Coordination Compounds","subtopicSlug":"nch-cc-cft","subtopicTitle":"Crystal Field Theory and Metal Carbonyls","conceptSlug":"nchcc-splitting","conceptName":"Crystal field splitting and the spectrochemical series","line":"Crystal field theory treats the ligands as negative charges (or the negative ends of dipoles) around the metal. In an octahedral complex the ligands come in along the x, y and z axes. The two d orbitals that point along the axes are pushed up in energy; the three that point between the axes are lower. The gap between the two sets is the crystal field splitting. A strong-field ligand makes a big gap, and then the d electrons would rather pair in the lower set than climb the gap.","pyqExampleId":"3c97a3c7-2a98-43ca-8213-a764c2666b62","badge":"picture","interactive":false},
  {"slug":"cet-sn1-vs-sn2","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"haloalkanes-and-haloarenes","chapterName":"Haloalkanes and Haloarenes","subtopicSlug":"nch-ha-substitution","subtopicTitle":"Nucleophilic Substitution","conceptSlug":"nchha-sn2","conceptName":"SN2 reactions and the products of substitution","line":"The carbon that holds the halogen is slightly positive, so an electron-rich nucleophile attacks it. In an SN2 reaction this happens in one step: the nucleophile comes in from the side opposite the halogen, and the new bond forms as the old one breaks. Bulky groups around that carbon get in the way, so the least crowded halides react fastest.","pyqExampleId":"5be81cf5-cc37-4f06-ba7d-1fb4656f8b4d","badge":"try","interactive":true},
  {"slug":"imat-chirality-mirror","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"haloalkanes-and-haloarenes","chapterName":"Haloalkanes and Haloarenes","subtopicSlug":"nch-ha-substitution","subtopicTitle":"Nucleophilic Substitution","conceptSlug":"nchha-stereo","conceptName":"Optical activity, chirality and the stereochemistry of substitution","line":"Your two hands are mirror images, but you cannot lay one exactly on top of the other. A carbon joined to four different groups is the same: its molecule and its mirror image are two different compounds. They behave alike in almost every way, except that they turn plane polarised light in opposite directions. Which one an SN1 or SN2 reaction gives depends on the side the nucleophile comes from.","pyqExampleId":"d2067d1f-f953-4ccc-b45a-2e6564d37018","badge":"picture","interactive":false},
  {"slug":"cet-saytzeff-elimination","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"haloalkanes-and-haloarenes","chapterName":"Haloalkanes and Haloarenes","subtopicSlug":"nch-ha-elimination","subtopicTitle":"Elimination and Haloarenes","conceptSlug":"nchha-saytzeff","conceptName":"Dehydrohalogenation and the Saytzeff rule","line":"The carbon that holds the halogen is the α-carbon; the carbons next to it are β-carbons. Alcoholic KOH pulls off a hydrogen from a β-carbon while the halogen leaves from the α-carbon, and a double bond forms between them. When there is more than one kind of β-hydrogen, more than one alkene can form, and the one with more alkyl groups on its double bond wins.","pyqExampleId":"61814716-525a-475e-9cff-cdf8b10a306c","badge":"picture","interactive":false},
  {"slug":"neet-phenol-acidity","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"alcohols-phenols-and-ethers","chapterName":"Alcohols, Phenols and Ethers","subtopicSlug":"nch-al-phenols-ethers","subtopicTitle":"Phenols and Ethers","conceptSlug":"nchal-acidity","conceptName":"Acidity of alcohols and phenols","line":"An acid is strong when the ion left behind after losing H⁺ is stable. In an alkoxide ion the negative charge stays on the oxygen. In the phenoxide ion the charge spreads into the benzene ring by resonance, so phenol gives up its proton far more readily. A group that pulls electrons from the ring spreads the charge further and makes the phenol stronger; a group that pushes electrons in makes it weaker.","pyqExampleId":"73704c23-a920-4838-9c5a-651b0374d630","badge":"picture","interactive":false},
  {"slug":"cet-carbonyl-addition","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"aldehydes-ketones-and-carboxylic-acids","chapterName":"Aldehydes, Ketones and Carboxylic Acids","subtopicSlug":"nch-ak-addition","subtopicTitle":"Nucleophilic Addition and Reduction","conceptSlug":"nchak-nucleophilic-addition","conceptName":"Nucleophilic addition to the carbonyl group","line":"Oxygen pulls the electrons of the C=O bond towards itself, leaving the carbon slightly positive. A nucleophile attacks that carbon, the π bond moves onto oxygen, and the flat carbon becomes tetrahedral. The oxygen then picks up a proton. With ammonia derivatives the addition product goes on to lose water, so a C=N bond replaces the C=O.","pyqExampleId":"cb4eec6b-4a06-4ab5-9208-3166ad5b8510","badge":"try","interactive":true},
  {"slug":"neet-amine-basicity","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"amines","chapterName":"Amines","subtopicSlug":"nch-am-reactions","subtopicTitle":"Basicity and Reactions of Amines","conceptSlug":"ncham-basicity","conceptName":"Basic strength of amines","line":"An amine is a base because the lone pair on its nitrogen can take a proton. Anything that makes that lone pair more available makes a stronger base. Alkyl groups push electrons onto nitrogen, so aliphatic amines are stronger bases than ammonia. In aniline the lone pair is spread into the benzene ring, so it is far less available, and aniline is a weaker base than ammonia.","pyqExampleId":"fd8848b6-c1d9-42d5-b62e-19e28ae35033","badge":"picture","interactive":false},
  {"slug":"cet-glucose-ring-closure","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"biomolecules","chapterName":"Biomolecules","subtopicSlug":"nch-bm-carbohydrates","subtopicTitle":"Carbohydrates","conceptSlug":"nchbm-glucose","conceptName":"Glucose: reactions and ring structure","line":"Each reaction of glucose answers one question about its open chain. HI removes every oxygen and leaves n-hexane, so the six carbons lie in a straight chain. Hydroxylamine and HCN show a carbonyl group, and bromine water shows that it is an aldehyde. Acetic anhydride counts five OH groups. But glucose fails some aldehyde tests and comes in two crystalline forms. A ring explains both: the OH at C-5 adds to the aldehyde group.","pyqExampleId":"7996bca4-088f-4301-8520-57b35e61257d","badge":"try","interactive":true},
  {"slug":"biochem-protein-structure-levels","examSlug":"neet","examName":"NEET","subjectName":"Chemistry","subjectRoute":"neet-chemistry","subjectDisplay":"NEET Chemistry","chapterSlug":"biomolecules","chapterName":"Biomolecules","subtopicSlug":"nch-bm-proteins","subtopicTitle":"Proteins and Enzymes","conceptSlug":"nchbm-protein-structure","conceptName":"Amino acids, peptides and protein structure","line":"A protein is a long chain of α-amino acids joined by peptide bonds. The order of amino acids in the chain is its primary structure. The chain then coils or folds, held mainly by hydrogen bonds, and some proteins pack several chains together. Heat or a change in pH breaks those weak bonds but not the peptide bonds, so the shape is lost and the sequence stays.","pyqExampleId":"5336d74a-cfdc-43ab-89bc-ddeda06ec42d","badge":"picture","interactive":false},
];

